select.ppmNorm:
@replace(
  replace(
    replace(
      toUpper(
        trim(
          string(
            coalesce(item()?['ppm'], '')
          )
        )
      ),
      '–',
      '-'
    ),
    '—',
    '-'
  ),
  '−',
  '-'
)

select.isRemeasure:
@or(
  equals(item()?['judgmentText'], '??'),
  equals(item()?['judgmentText'], '※'),
  equals(item()?['judgmentText'], 'CANNOT JUDGE'),
  equals(item()?['judgmentText'], 'CANNOT BE JUDGED')
)

select.numericPpm:
@if(
  isFloat(
    replace(
      item()?['ppmNorm'],
      ',',
      ''
    )
  ),
  float(
    replace(
      item()?['ppmNorm'],
      ',',
      ''
    )
  ),
  0
)

select.level:
@if(
  item()?['isRemeasure'],
  '',
  if(
    item()?['isND'],
    'L',
    if(
      or(
        item()?['isMissing'],
        not(item()?['isNumeric'])
      ),
      '',
      if(
        and(
          equals(item()?['numericPpm'], 0),
          or(
            equals(item()?['judgmentText'], 'ND'),
            equals(item()?['judgmentText'], 'N.D.'),
            equals(item()?['judgmentText'], 'N.D'),
            equals(item()?['judgmentText'], 'NOT DETECTED'),
            equals(item()?['judgmentText'], 'NON DETECTED'),
            equals(item()?['judgmentText'], '불검출')
          )
        ),
        'L',
        if(
          greater(
            item()?['numericPpm'],
            item()?['internalLimit']
          ),
          'H',
          'M'
        )
      )
    )
  )
)

Compose_Initial_ClBr_Level.inputs:
@if(
  or(
    empty(outputs('Compose_Initial_Cl')),
    empty(outputs('Compose_Initial_Br')),
    empty(outputs('Compose_Initial_Cl')?['level']),
    empty(outputs('Compose_Initial_Br')?['level'])
  ),
  '',
  if(
    and(
      equals(outputs('Compose_Initial_Cl')?['isND'], true),
      equals(outputs('Compose_Initial_Br')?['isND'], true)
    ),
    'L',
    if(
      greater(
        add(
          outputs('Compose_Initial_Cl')?['numericPpm'],
          outputs('Compose_Initial_Br')?['numericPpm']
        ),
        1050
      ),
      'H',
      'M'
    )
  )
)

Compose_Initial_XRF_Level.inputs:
@if(
  or(
    not(
      equals(
        length(body('Filter_Initial_Elements')),
        6
      )
    ),
    greater(
      length(body('Filter_Initial_InvalidLevel')),
      0
    ),
    empty(outputs('Compose_Initial_ClBr_Level'))
  ),
  '',
  if(
    or(
      greater(
        length(body('Filter_Initial_H')),
        0
      ),
      equals(
        outputs('Compose_Initial_ClBr_Level'),
        'H'
      )
    ),
    'H',
    if(
      or(
        greater(
          length(body('Filter_Initial_M')),
          0
        ),
        equals(
          outputs('Compose_Initial_ClBr_Level'),
          'M'
        )
      ),
      'M',
      'L'
    )
  )
)

Compose_Final_Risk.inputs:
@if(
  empty(outputs('Compose_Initial_XRF_Level')),
  '',
  if(
    equals(
      outputs('Compose_Initial_XRF_Level'),
      'H'
    ),
    'Not Allowed',
    if(
      equals(
        outputs('Compose_Initial_XRF_Level'),
        'M'
      ),
      if(
        equals(
          outputs('Compose_CR_Level'),
          'H'
        ),
        'H',
        'M'
      ),
      if(
        equals(
          outputs('Compose_Initial_XRF_Level'),
          'L'
        ),
        if(
          equals(
            outputs('Compose_CR_Level'),
            'L'
          ),
          'L',
          'M'
        ),
        ''
      )
    )
  )
)

Compose_Cycle.inputs:
@if(
  equals(
    outputs('Compose_Final_Risk'),
    'H'
  ),
  'Monthly',
  if(
    equals(
      outputs('Compose_Final_Risk'),
      'M'
    ),
    'Semiannual',
    if(
      equals(
        outputs('Compose_Final_Risk'),
        'L'
      ),
      'Annual',
      'Not Available'
    )
  )
)

Compose_CycleMonths.inputs:
@if(
  equals(
    outputs('Compose_Cycle'),
    'Monthly'
  ),
  1,
  if(
    equals(
      outputs('Compose_Cycle'),
      'Semiannual'
    ),
    6,
    if(
      equals(
        outputs('Compose_Cycle'),
        'Annual'
      ),
      12,
      0
    )
  )
)

Compose_WindowDays.inputs:
@if(
  equals(
    outputs('Compose_Cycle'),
    'Monthly'
  ),
  15,
  if(
    or(
      equals(
        outputs('Compose_Cycle'),
        'Semiannual'
      ),
      equals(
        outputs('Compose_Cycle'),
        'Annual'
      )
    ),
    30,
    0
  )
)

Compose_CycleLabel.inputs:
@if(
  equals(
    outputs('Compose_Cycle'),
    'Monthly'
  ),
  '월 1회',
  if(
    equals(
      outputs('Compose_Cycle'),
      'Semiannual'
    ),
    '반기 1회',
    if(
      equals(
        outputs('Compose_Cycle'),
        'Annual'
      ),
      '연 1회',
      '-'
    )
  )
)

Compose_FirstDueDate.inputs:
@if(
  or(
    empty(outputs('Compose_BaseDate')),
    equals(
      outputs('Compose_CycleMonths'),
      0
    )
  ),
  '',
  addToTime(
    outputs('Compose_BaseDate'),
    outputs('Compose_CycleMonths'),
    'Month',
    'yyyy-MM-dd'
  )
)

inputs.where:
@equals(and(
  not(
    equals(
      item()?['role'],
      'Retest'
    )
  ),
  not(
    empty(
      item()?['date']
    )
  ),
  greater(
    ticks(item()?['date']),
    ticks(outputs('Compose_BaseDate'))
  )
),true)

Compose_PeriodPrevDue.inputs:
@if(
  equals(
    variables('vPeriodNo'),
    1
  ),
  outputs('Compose_BaseDate'),
  addToTime(
    outputs('Compose_BaseDate'),
    mul(
      sub(
        variables('vPeriodNo'),
        1
      ),
      outputs('Compose_CycleMonths')
    ),
    'Month',
    'yyyy-MM-dd'
  )
)

inputs.where:
@equals(and(
  not(
    contains(
      variables('vConsumedMeasurementIds'),
      item()?['measurementId']
    )
  ),
  if(
    equals(
      outputs('Compose_Cycle'),
      'Annual'
    ),
    equals(
      formatDateTime(
        item()?['date'],
        'yyyy'
      ),
      formatDateTime(
        outputs('Compose_PeriodDue'),
        'yyyy'
      )
    ),
    and(
      greater(
        ticks(
          concat(
            item()?['date'],
            'T00:00:00Z'
          )
        ),
        ticks(
          concat(
            outputs('Compose_PeriodPrevDue'),
            'T00:00:00Z'
          )
        )
      ),
      less(
        ticks(
          concat(
            item()?['date'],
            'T00:00:00Z'
          )
        ),
        ticks(
          concat(
            outputs('Compose_PeriodNextDue'),
            'T00:00:00Z'
          )
        )
      )
    )
  )
),true)

inputs.value:
@addProperty(
  addProperty(
    addProperty(
      json('{}'),
      'measurementId',
      string(
        items('Apply_to_each_AnnualPeriodMeasurement')?['measurementId']
      )
    ),
    'itemId',
    string(
      items('Apply_to_each_Item')?['itemId']
    )
  ),
  'period',
  concat(
    'P',
    string(variables('vPeriodNo'))
  )
)

@addProperty(
  addProperty(
    addProperty(
      json('{}'),
      'measurementId',
      string(
        outputs('Compose_CurrentPeriodCandidate')?['measurementId']
      )
    ),
    'itemId',
    string(
      items('Apply_to_each_Item')?['itemId']
    )
  ),
  'period',
  concat(
    'P',
    string(variables('vPeriodNo'))
  )
)

equals:
@greater(
  ticks(
    concat(
      outputs('Compose_AsOfDate'),
      'T00:00:00Z'
    )
  ),
  ticks(
    concat(
      outputs('Compose_PeriodDue'),
      'T00:00:00Z'
    )
  )
)

@and(
  not(
    empty(
      variables('vNextOpenDue')
    )
  ),
  not(
    empty(
      variables('vNextOpenWindowStart')
    )
  ),
  greaterOrEquals(
    ticks(
      concat(
        outputs('Compose_AsOfDate'),
        'T00:00:00Z'
      )
    ),
    ticks(
      concat(
        variables('vNextOpenWindowStart'),
        'T00:00:00Z'
      )
    )
  )
)

@or(
  equals(
    outputs('Compose_Cycle'),
    'Monthly'
  ),
  equals(
    outputs('Compose_Cycle'),
    'Semiannual'
  ),
  equals(
    outputs('Compose_Cycle'),
    'Annual'
  )
)

@and(
  equals(
    variables('vPeriodicStatus'),
    '측정권장'
  ),
  not(
    empty(
      variables('vPeriodicDueDate')
    )
  ),
  not(
    equals(
      items('Apply_to_each_Item')?['type'],
      'Facility'
    )
  ),
  not(
    equals(
      items('Apply_to_each_Item')?['lifecycle'],
      'ReplacedOld'
    )
  ),
  not(
    equals(
      items('Apply_to_each_Item')?['lifecycle'],
      'Discontinued'
    )
  ),
  equals(
    items('Apply_to_each_Item')?['isCurrent'],
    true
  ),
  or(
    equals(
      outputs('Compose_Final_Risk'),
      'H'
    ),
    equals(
      outputs('Compose_Final_Risk'),
      'M'
    ),
    equals(
      outputs('Compose_Final_Risk'),
      'L'
    )
  )
)
